              value: state.renameName,
              isDisabled: state.renameBusy,
              onInput: actions.onRenameNameChange,
            },
            h,
          ),
          textField(
            {
              id: "rename-team-tz",
              label: message("teams.create.timeZone"),
              value: state.renameTimeZone,
              isDisabled: state.renameBusy,
              onInput: actions.onRenameTimeZoneChange,
            },
            h,
          ),
          problemView(state.renameFailure, h),
          appButton(
            {
              text: message("team.rename.action"),
              type: "submit",
              isDisabled: state.renameBusy,
            },
            h,
          ),
        ].filter(Predicate.isNotNull),
      ),
    );
  }

  // Roster
  children.push(h.div([h.Class("mt-8")], [subSectionTitle(message("team.roster"), h, 2)]));
  children.push(
    h.ul(
      [h.Class("mt-3 rounded-panel border border-line bg-surface px-6")],
      detail.roster.map((entry) => {
        const isLead = entry.role === "lead";
        const mayRemove = isLead ? detail.may.manageLeads : detail.may.manageMembers;
        return h.li(
          [h.Class("flex items-center justify-between gap-4 border-b border-line-soft py-3 last:border-b-0")],
          [
            h.span(
              [h.Class("flex flex-wrap items-center gap-x-3 gap-y-1")],
              [
                h.span([h.Class("font-medium")], [entry.email]),
                badge("neutral", [roleName(entry.role)], h),
                h.span(
                  [h.Class("text-sm text-muted")],
                  [message("team.since", { date: formatDate(new Date(entry.since)) })],
                ),
              ],
            ),
            mayRemove
              ? appButton(
                  {
                    text: message(isLead ? "team.removeLead" : "team.removeMember"),
                    isDisabled: state.rosterBusy,
                    className: linkButton,
                    onClick: isLead
                      ? actions.onRemoveLead(entry.personId)
                      : actions.onRemoveMember(entry.personId),
                  },
                  h,
                )

                )
              : null,
          ].filter(Predicate.isNotNull),
        );
      }),
    ),
  );
  if (state.rosterFailure) {
    children.push(problemView(state.rosterFailure, h)!);
  }

  // Add Member
  if (detail.may.manageMembers) {
    children.push(
      h.form(
        [h.Class(formPanelClass), h.OnSubmit(actions.onSubmitAddMember)],
        [
          textField(
            {
              id: "add-member-email",
              label: message("team.addMember.label"),
              value: state.addMemberEmail,
              type: "email",
              isDisabled: state.addMemberBusy,
              onInput: actions.onAddMemberEmailChange,
            },
            h,
          ),
          problemView(state.addMemberFailure, h),
          state.addMemberAdded
            ? h.p([h.Role("status"), h.Class("text-sm font-medium text-primary")], [message("team.added")])
            : null,
          appButton(
            {
              text: message("team.addMember.action"),
              type: "submit",
              isDisabled: state.addMemberBusy,
            },
            h,
          ),
        ].filter(Predicate.isNotNull),
      ),
    );
  }

  // Assign Lead
  if (detail.may.manageLeads) {
    children.push(
      h.form(
        [h.Class(formPanelClass), h.OnSubmit(actions.onSubmitAssignLead)],
        [
          textField(
            {
              id: "assign-lead-email",
              label: message("team.assignLead.label"),
              value: state.assignLeadEmail,
              type: "email",
              isDisabled: state.assignLeadBusy,
              onInput: actions.onAssignLeadEmailChange,
            },
            h,
          ),
          problemView(state.assignLeadFailure, h),
          state.assignLeadAdded
            ? h.p([h.Role("status"), h.Class("text-sm font-medium text-primary")], [message("team.added")])
            : null,
          appButton(
            {
              text: message("team.assignLead.action"),
              type: "submit",
              isDisabled: state.assignLeadBusy,
            },
            h,
          ),
        ].filter(Predicate.isNotNull),
      ),
    );
  }

  return h.section([], children);
};

export const settingsScreenView = <Message>(
  state: {
    readonly settings: LoadedSettings;
    readonly size: string;
    readonly sizeSaved: boolean;
    readonly sizeBusy: boolean;
    readonly sizeFailure?: Failure | undefined;
    readonly aiBusy: boolean;
    readonly aiFailure?: Failure | undefined;
    readonly peopleBusy: boolean;
    readonly peopleFailure?: Failure | undefined;
  },
  actions: {
    readonly onSizeChange: (size: string) => Message;
    readonly onSubmitSize: Message;
    readonly onAiProcessingToggle: (isOn: boolean) => Message;
    readonly onGrantAdmin: (personId: PersonId) => Message;
    readonly onRevokeAdmin: (personId: PersonId) => Message;
    readonly onRemovePerson: (personId: PersonId) => Message;
  },
  h: HtmlBuilder<Message>,
): Html => {
  const children: Array<Child> = [pageTitle(message("settings.title"), h)];

  if (state.settings._tag === "Failed") {
    children.push(problemView(state.settings.failure, h)!);
    return h.section([], children);
  }

  if (state.settings._tag !== "Loaded") {
    return h.section([], children);
  }

  const { settings } = state.settings;

  // MinimumGroupSizeForm
  children.push(
    h.form(
      [h.Class(formPanelClass), h.OnSubmit(actions.onSubmitSize)],
      [
        textField(
          {
            id: "min-group-size",
            label: message("settings.minimumGroupSize"),
            value: state.size,
            type: "number",
            isDisabled: state.sizeBusy,
            onInput: actions.onSizeChange,
          },
          h,
        ),
        h.p([h.Class("text-sm text-muted")], [message("settings.minimumGroupSize.help")]),
        problemView(state.sizeFailure, h),
        state.sizeSaved
          ? h.p([h.Role("status"), h.Class("text-sm font-medium text-primary")], [message("settings.saved")])
          : null,
        appButton(
          {
            text: message("settings.save"),
            type: "submit",
            isDisabled: state.sizeBusy,
          },
          h,
        ),
      ].filter(Predicate.isNotNull),
    ),
  );

  // AiProcessing
  children.push(
    h.div(
      [h.Class(formPanelClass)],
      [
        subSectionTitle(message("settings.aiProcessing.title"), h, 2),
        checkboxField(
          {
            id: "ai-processing",
            label: message("settings.aiProcessing.label"),
            isChecked: settings.aiProcessing,
            isDisabled: state.aiBusy,
            onToggle: actions.onAiProcessingToggle,
          },
          h,
        ),
        h.p([h.Class("text-sm text-muted")], [message("settings.aiProcessing.help")]),
        problemView(state.aiFailure, h),
      ].filter(Predicate.isNotNull),
    ),
  );

  // People
  children.push(h.div([h.Class("mt-8")], [subSectionTitle(message("settings.people"), h, 2)]));
  children.push(
    h.ul(
      [h.Class("mt-3 rounded-panel border border-line bg-surface px-6")],
      settings.people.map((person) => {
        const personId = decodePerson(person.personId);
        return h.li(
          [h.Class("border-b border-line-soft py-3 last:border-b-0")],
          [
            h.p(
              [h.Class("flex flex-wrap items-center gap-2 font-medium")],
              [
                person.email,
                person.organizationAdmin ? badge("primary", [message("settings.admin")], h) : null,
                person.linked ? null : badge("neutral", [message("settings.notSignedInYet")], h),
              ].filter(Predicate.isNotNull),
            ),
            h.div(
              [h.Class("flex gap-4")],
              [
                appButton(
                  {
                    text: message(person.organizationAdmin ? "settings.revokeAdmin" : "settings.makeAdmin"),
                    isDisabled: state.peopleBusy,
                    className: linkButton,
                    onClick: person.organizationAdmin
                      ? actions.onRevokeAdmin(person.personId)
                      : actions.onGrantAdmin(person.personId),
                  },
                  h,
                ),
                Option.isSome(personId)
                  ? appButton(
                      {
                        text: message("settings.removePerson"),
                        isDisabled: state.peopleBusy,
                        className: linkButton,
                        onClick: actions.onRemovePerson(person.personId),
                      },
                      h,
                    )
                  : null,
              ].filter(Predicate.isNotNull),
            ),
          ],
        );
      }),
    ),
  );

  if (state.peopleFailure) {
    children.push(problemView(state.peopleFailure, h)!);
  }

  return h.section([], children);
};

import { Button, Checkbox, Input, Select, Textarea } from "@foldkit/ui";
import { Predicate } from "effect";
import type { Html, HtmlBuilder } from "foldkit/html";
import { message } from "../messages/index.ts";
import { type Failure, failureMessage } from "./api.ts";
import { teamsHref } from "./routes.ts";

export type Child = Html | string;

export const buttonClass =
  "inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-5 py-2 font-semibold text-on-primary hover:bg-primary-hover disabled:opacity-50";
export const secondaryButtonClass =
  "inline-flex min-h-11 items-center justify-center rounded-control border border-line bg-surface px-5 py-2 font-semibold text-ink hover:bg-subtle disabled:opacity-50";
export const mintButtonClass =
  "inline-flex min-h-11 items-center justify-center rounded-control bg-mint px-5 py-2 font-semibold text-evergreen hover:bg-mint-text disabled:opacity-50";
export const darkOutlineButtonClass =
  "inline-flex min-h-11 items-center justify-center rounded-control border border-mint-text px-4 py-2 font-semibold text-white hover:bg-evergreen-raised disabled:opacity-50";
export const linkButton =
  "inline-flex min-h-11 items-center px-1 text-sm font-semibold text-primary underline underline-offset-4 hover:text-primary-hover disabled:opacity-50";
export const linkClass = "font-semibold text-primary underline underline-offset-4 hover:text-primary-hover";
export const labelClass = "block text-[15px] font-semibold";
export const inputClass =
  "mt-1.5 min-h-11 w-full rounded-control border border-line bg-surface px-3 py-2 text-base text-ink disabled:opacity-60";

export const brandMark = <Message>(h: HtmlBuilder<Message>): Html =>
  h.svg(
    [h.Width("28"), h.Height("28"), h.ViewBox("0 0 28 28"), h.AriaHidden(true)],
    [
      h.rect([h.Width("28"), h.Height("28"), h.Rx("8"), h.Fill("#0E2A24")]),
      h.path([
        h.D("M6 14h4l2-5 4 10 2-5h4"),
        h.Fill("none"),
        h.Stroke("#9FD6CB"),
        h.StrokeWidth("1.8"),
        h.StrokeLinecap("round"),
        h.StrokeLinejoin("round"),
      ]),
    ],
  );

export const navLink = <Message>(href: string, text: string, h: HtmlBuilder<Message>): Html =>
  h.a(
    [h.Href(href), h.Class("inline-flex min-h-11 items-center font-medium text-muted hover:text-ink")],
    [text],
  );

/** Header bar plus the content column; `wide` makes room for a side column. */
export const pageShell = <Message>(
  config: {
    readonly organizationName?: string | undefined;
    readonly nav?: ReadonlyArray<Child> | undefined;
    readonly wide?: boolean | undefined;
  },
  children: ReadonlyArray<Child>,
  h: HtmlBuilder<Message>,
): Html =>
  h.div(
    [h.Class("min-h-screen bg-stone text-ink")],
    [
      h.header(
        [h.Class("border-b border-line bg-surface")],
        [
          h.div(
            [h.Class("mx-auto flex max-w-[1120px] flex-wrap items-center gap-x-5 gap-y-1 px-6 py-2 sm:px-8")],
            [
              h.span(
                [h.Class("flex items-center gap-2.5")],
                [
                  brandMark(h),
                  h.span([h.Class("text-[17px] font-bold tracking-tight")], [message("app.title")]),
                ],
              ),
              config.organizationName !== undefined
                ? h.span(
                    [h.Class("border-l border-line pl-5 text-[15px] font-semibold")],
                    [config.organizationName],
                  )
                : null,
              config.nav !== undefined && config.nav.length > 0
                ? h.nav([h.Class("ml-auto flex flex-wrap gap-x-6 text-[15px]")], config.nav)
                : null,
            ].filter(Predicate.isNotNull),
          ),
        ],
      ),
      h.main(
        [
          h.Class(
            `mx-auto px-6 pt-8 pb-20 sm:px-8 sm:pt-12 ${config.wide === true ? "max-w-[1120px]" : "max-w-[720px] sm:mx-auto"}`,
          ),
        ],
        children,
      ),
    ],
  );

export const screenView = <Message>(
  title: string,
  children: ReadonlyArray<Child>,
  h: HtmlBuilder<Message>,
): Html => pageShell({}, [pageTitle(title, h), ...children], h);

export const pageTitle = <Message>(text: string, h: HtmlBuilder<Message>): Html =>
  h.h1(
    [h.Class("font-display text-[32px] leading-[1.15] font-normal tracking-tight text-ink sm:text-[44px]")],
    [text],
  );

export const sectionTitle = <Message>(text: string, h: HtmlBuilder<Message>): Html =>
  h.h2([h.Class("font-display text-[30px] leading-tight font-normal text-ink")], [text]);

export const subSectionTitle = <Message>(
  text: string,
  h: HtmlBuilder<Message>,
  level: 2 | 3 | 4 = 3,
): Html => {
  const attrs = [h.Class("text-[19px] leading-snug font-semibold text-ink")];
  return level === 2 ? h.h2(attrs, [text]) : level === 3 ? h.h3(attrs, [text]) : h.h4(attrs, [text]);
};

export const panel = <Message>(
  children: ReadonlyArray<Child>,
  h: HtmlBuilder<Message>,
  className = "",
): Html =>
  h.div([h.Class(`rounded-panel border border-line bg-surface p-6 sm:p-8 ${className}`.trim())], children);

export const darkPanel = <Message>(
  children: ReadonlyArray<Child>,
  h: HtmlBuilder<Message>,
  className = "",
): Html =>
  h.div(
    [
      h.Class(
        `rounded-panel bg-evergreen p-6 text-white sm:p-8 [&_:focus-visible]:outline-mint ${className}`.trim(),
      ),
    ],
    children,
  );

export const alertView = <Message>(text: string, h: HtmlBuilder<Message>): Html =>
  h.p(
    [
      h.Role("alert"),
      h.Class("mt-2 rounded-control bg-danger-soft px-4 py-3 text-sm font-medium text-danger"),
    ],
    [text],
  );

export const emptyState = <Message>(text: string, h: HtmlBuilder<Message>): Html =>
  h.p(
    [
      h.Class(
        "mt-3 rounded-control border border-dashed border-line bg-subtle px-4 py-6 text-center text-muted",
      ),
    ],
    [text],
  );

export type BadgeVariant = "neutral" | "primary" | "brass";

const badgeClasses: Record<BadgeVariant, string> = {
  neutral: "bg-line-soft text-muted",
  primary: "bg-primary-soft text-primary-hover",
  brass: "bg-brass-soft text-brass",
};

export const badge = <Message>(
  variant: BadgeVariant,
  children: ReadonlyArray<Child>,
  h: HtmlBuilder<Message>,
): Html =>
  h.span(
    [
      h.Class(
        `inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-[13px] font-semibold ${badgeClasses[variant]}`,
      ),
    ],
    children,
  );

export const dataTable = <Message>(
  headers: ReadonlyArray<string>,
  rows: ReadonlyArray<ReadonlyArray<string>>,
  h: HtmlBuilder<Message>,
): Html =>
  h.table(
    [h.Class("mt-2 w-full text-left text-sm")],
    [
      h.thead(
        [],
        [
          h.tr(
            [h.Class("border-b border-line-soft")],
            headers.map((header) =>
              h.th([h.Class("py-2 pr-4 text-[13px] font-semibold text-muted")], [header]),
            ),
          ),
        ],
      ),
      h.tbody(
        [],
        rows.map((row) =>
          h.tr(
            [h.Class("border-b border-line-soft last:border-b-0")],
            row.map((cell) => h.td([h.Class("py-2 pr-4 tabular-nums")], [cell])),
          ),
        ),
      ),
    ],
  );

export const statList = <Message>(
  items: ReadonlyArray<readonly [label: string, value: string]>,
  h: HtmlBuilder<Message>,
): Html =>
  h.dl(
    [h.Class("grid grid-cols-[1fr_auto] gap-x-4 gap-y-3 text-sm")],
    items.flatMap(([label, value]) => [
      h.dt([h.Class("text-muted")], [label]),
      h.dd([h.Class("m-0 font-semibold tabular-nums")], [value]),
    ]),
  );

export const problemView = <Message>(failure: Failure | undefined, h: HtmlBuilder<Message>): Html | null => {
  if (failure === undefined) return null;
  return alertView(failureMessage(failure), h);
};

export const appButton = <Message>(
  config: {
    readonly text: string;
    readonly onClick?: Message | undefined;
    readonly isDisabled?: boolean | undefined;
    readonly type?: "button" | "submit" | "reset" | undefined;
    readonly className?: string | undefined;
  },
  h: HtmlBuilder<Message>,
): Html =>
  Button.view(
    {
      toView: ({ button }) =>
        h.button(
          [
            ...button,
            ...(config.isDisabled ? [h.Disabled(true)] : []),
            h.Class(config.className ?? buttonClass),
          ],
          [config.text],
        ),
      type: config.type ?? "button",
      ...(config.onClick !== undefined ? { onClick: config.onClick } : {}),
      ...(config.isDisabled !== undefined ? { isDisabled: config.isDisabled } : {}),
    },
    h,
  );

export const textField = <Message>(
  config: {
    readonly id: string;
    readonly label: string;
    readonly value: string;
    readonly onInput: (value: string) => Message;
    readonly type?: "text" | "email" | "number" | "time" | undefined;
    readonly isDisabled?: boolean | undefined;
    readonly maxLength?: number | undefined;
  },
  h: HtmlBuilder<Message>,
): Html =>
  Input.view(
    {
      id: config.id,
      value: config.value,
      type: config.type ?? "text",
      toView: ({ input, label }) =>
        h.div(
          [h.Class("flex flex-col")],
          [
            h.label([...label, h.Class(labelClass)], [config.label]),
            h.input([
              ...input,
              ...(config.maxLength !== undefined ? [h.Maxlength(config.maxLength)] : []),
              h.Class(inputClass),
            ]),
          ],
        ),
      onInput: config.onInput,
      ...(config.isDisabled !== undefined ? { isDisabled: config.isDisabled } : {}),
    },
    h,
  );

export const selectField = <Message, V extends string | number>(
  config: {
    readonly id: string;
    readonly label: string;
    readonly value: V;
    readonly options: ReadonlyArray<readonly [V, string]>;
    readonly onChange: (value: string) => Message;
    readonly isDisabled?: boolean | undefined;
  },
  h: HtmlBuilder<Message>,
): Html =>
  Select.view(
    {
      id: config.id,
      value: String(config.value),
      toView: ({ select, label }) =>
        h.div(
          [h.Class("flex flex-col")],
          [
            h.label([...label, h.Class(labelClass)], [config.label]),
            h.select(
              [...select, h.Class(inputClass)],
              config.options.map(([opt, name]) => h.option([h.Value(String(opt))], [name])),
            ),
          ],
        ),
      onChange: config.onChange,
      ...(config.isDisabled !== undefined ? { isDisabled: config.isDisabled } : {}),
    },
    h,
  );

export const textareaField = <Message>(
  config: {
    readonly id: string;
    readonly label: string;
    readonly value: string;
    readonly onInput: (value: string) => Message;
    readonly rows?: number | undefined;
    readonly isDisabled?: boolean | undefined;
  },
  h: HtmlBuilder<Message>,
): Html =>
  Textarea.view(
    {
      id: config.id,
      value: config.value,
      rows: config.rows ?? 4,
      toView: ({ textarea, label }) =>
        h.div(
          [h.Class("flex flex-col")],
          [
            h.label([...label, h.Class(labelClass)], [config.label]),
            h.textarea([...textarea, h.Class(inputClass)]),
          ],
        ),
      onInput: config.onInput,
      ...(config.isDisabled !== undefined ? { isDisabled: config.isDisabled } : {}),
    },
    h,
  );

export const checkboxField = <Message>(
  config: {
    readonly id: string;
    readonly label: string;
    readonly isChecked: boolean;
    readonly onToggle: (isChecked: boolean) => Message;
    readonly isDisabled?: boolean | undefined;
  },
  h: HtmlBuilder<Message>,
): Html =>
  Checkbox.view(
    {
      id: config.id,
      isChecked: config.isChecked,
      toView: ({ checkbox, label }) =>
        h.label(
          [...label, h.Class("flex min-h-11 items-center gap-3 text-[15px]")],
          [
            h.input([
              ...checkbox,
              h.Type("checkbox"),
              h.Checked(config.isChecked),
              h.Class("size-5 accent-primary"),
            ]),
            config.label,
          ],
        ),
      onToggle: config.onToggle,
      ...(config.isDisabled !== undefined ? { isDisabled: config.isDisabled } : {}),
    },
    h,
  );

export const signOutView = <Message>(h: HtmlBuilder<Message>): Html =>
  h.form(
    [h.Method("post"), h.Action("/auth/logout"), h.Class("mt-10")],
    [
      Button.view(
        {
          type: "submit",
          toView: ({ button }) => h.button([...button, h.Class(linkButton)], [message("signOut.action")]),
        },
        h,
      ),
    ],
  );

export const privacyView = <Message>(h: HtmlBuilder<Message>): Html =>
  screenView(
    message("privacy.title"),
    [
      h.p([h.Class("mt-4")], [h.a([h.Href(teamsHref()), h.Class(linkClass)], [message("privacy.back")])]),
      panel(
        [
          h.div(
            [h.Class("flex flex-col gap-6 leading-relaxed text-muted")],
