            ).map(([title, body]) =>
              h.div([], [subSectionTitle(message(title), h, 2), h.p([h.Class("mt-1")], [message(body)])]),
            ),
          ),
        ],
        h,
        "mt-6",
      ),
    ],
    h,
  );

